//! Golden-vector tests generated by the Python reference.
//!
//! The JSON files live in `rust/fixtures/golden/`; regenerate them with
//! `just fixtures` (see `scripts/gen_fixtures.py`). These tests prove that the
//! Rust framing, capacity and formatting match the Python oracle, and that the
//! committed fixtures have not been modified by hand.

use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

use rawhide_core::{
    LsbCodec, PayloadFrame, capacity_bytes_total, format_kb, format_kb_hi, format_kb_lo,
};
use serde_json::Value;
use sha2::{Digest, Sha256};

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures")
        .canonicalize()
        .expect("fixtures directory must exist")
}

fn read_json(name: &str) -> Value {
    let path = fixtures_dir().join("golden").join(name);
    let text = fs::read_to_string(&path).unwrap_or_else(|error| {
        panic!("cannot read {}: {error}", path.display());
    });
    serde_json::from_str(&text).unwrap_or_else(|error| {
        panic!("cannot parse {}: {error}", path.display());
    })
}

fn decode_hex(value: &str) -> Vec<u8> {
    assert!(value.len().is_multiple_of(2), "odd-length hex string");
    let (pairs, _remainder) = value.as_bytes().as_chunks::<2>();
    pairs
        .iter()
        .map(|pair| {
            let text = std::str::from_utf8(pair).expect("hex is ASCII");
            u8::from_str_radix(text, 16).expect("valid hex")
        })
        .collect()
}

fn as_str<'a>(value: &'a Value, key: &str) -> &'a str {
    value
        .get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("missing string field {key}"))
}

fn as_u16_array(value: &Value, key: &str) -> Vec<u16> {
    value
        .get(key)
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("missing array field {key}"))
        .iter()
        .map(|item| {
            u16::try_from(item.as_u64().unwrap_or_else(|| panic!("{key} item")))
                .unwrap_or_else(|_| panic!("{key} item does not fit in u16"))
        })
        .collect()
}

#[test]
fn framing_vectors_match_python() {
    let golden = read_json("framing.json");
    let payload = decode_hex(as_str(&golden, "payload_hex"));
    let key = decode_hex(as_str(&golden, "key_hex"));

    let keyed = PayloadFrame::pack(&payload, Some(&key));
    assert_eq!(keyed, decode_hex(as_str(&golden, "frame_keyed_hex")));
    assert_eq!(PayloadFrame::unpack(&keyed, Some(&key)).unwrap().0, payload);

    let plain = PayloadFrame::pack(&payload, None);
    assert_eq!(plain, decode_hex(as_str(&golden, "frame_plain_hex")));

    let empty = PayloadFrame::pack(b"", None);
    assert_eq!(empty, decode_hex(as_str(&golden, "frame_empty_hex")));

    let keystream = PayloadFrame::keystream_range(&key, 0, 64);
    assert_eq!(keystream, decode_hex(as_str(&golden, "keystream_0_64_hex")));

    let header_len = golden
        .get("header_len")
        .and_then(Value::as_u64)
        .expect("header_len");
    assert_eq!(
        usize::try_from(header_len).unwrap(),
        PayloadFrame::HEADER_LEN
    );
}

#[test]
fn capacity_vectors_match_python() {
    let golden = read_json("capacity.json");
    let cases = golden
        .get("cases")
        .and_then(Value::as_array)
        .expect("cases array");
    assert_ne!(cases.len(), 0);

    for case in cases {
        let samples = case
            .get("n_samples_per_frame")
            .and_then(Value::as_u64)
            .expect("n_samples_per_frame");
        let planes = case
            .get("lsb_planes")
            .and_then(Value::as_u64)
            .expect("lsb_planes") as u8;
        let frames = case.get("frames").and_then(Value::as_u64).expect("frames");
        let capacity = case
            .get("capacity")
            .and_then(Value::as_u64)
            .expect("capacity");

        assert_eq!(capacity_bytes_total(samples, planes, frames), capacity);
        if frames == 1 {
            assert_eq!(LsbCodec::new(planes).unwrap().capacity(samples), capacity);
        }
        assert_eq!(format_kb(capacity), as_str(case, "format_kb"));
        assert_eq!(format_kb_hi(capacity), as_str(case, "format_kb_hi"));
        assert_eq!(format_kb_lo(capacity), as_str(case, "format_kb_lo"));
    }
}

#[test]
fn codec_mapping_matches_python() {
    let golden = read_json("codec.json");
    let mut cover = as_u16_array(&golden, "cover");
    let expected = as_u16_array(&golden, "embedded");
    let frame = decode_hex(as_str(&golden, "frame_hex"));
    let planes = golden
        .get("lsb_planes")
        .and_then(Value::as_u64)
        .expect("lsb_planes") as u8;

    let codec = LsbCodec::new(planes).unwrap();
    codec.embed(&mut cover, &frame).unwrap();
    assert_eq!(cover, expected);
    assert_eq!(codec.extract(&cover, frame.len()).unwrap(), frame);
}

#[test]
fn committed_fixtures_match_manifest() {
    let root = fixtures_dir();
    let manifest_text = fs::read_to_string(root.join("manifest.json"))
        .expect("manifest.json is committed and readable");
    let manifest: Value = serde_json::from_str(&manifest_text).expect("valid manifest JSON");
    let files = manifest
        .get("files")
        .and_then(Value::as_array)
        .expect("files array");
    assert!(!files.is_empty(), "manifest must list fixtures");

    for entry in files {
        let relative = as_str(entry, "path");
        let expected_size = entry.get("bytes").and_then(Value::as_u64).expect("bytes");
        let expected_hash = as_str(entry, "sha256");
        let path = root.join(relative);
        let data = fs::read(&path)
            .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
        assert_eq!(data.len() as u64, expected_size, "{relative} size");
        let digest = Sha256::digest(&data);
        let mut actual_hash = String::with_capacity(digest.len() * 2);
        for byte in digest {
            write!(&mut actual_hash, "{byte:02x}").expect("writing to String cannot fail");
        }
        assert_eq!(actual_hash, expected_hash, "{relative} sha256");
    }
}
